from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        m = len(queries)

        def feasible(k: int) -> bool:
            for i in range(n):
                target = nums[i]
                if target == 0:
                    continue
                reachable = 1  # bit 0 represents sum 0
                hit = False
                for j in range(k):
                    l, r, v = queries[j]
                    if l <= i <= r:
                        reachable |= reachable << v
                        if (reachable >> target) & 1:
                            hit = True
                            break
                if not hit and not ((reachable >> target) & 1):
                    return False
            return True

        # If even using all queries we cannot achieve zero array, return -1
        if not feasible(m):
            return -1

        lo, hi = 0, m
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
